function openFirdaEscStep(id){
  const step=firdaEscItems().find(x=>x.id===id);if(!step)return;
  activeFirdaEscStep=id;
  if(step.target){openDomainTuning(step.target,'firda');if(selectedExperiment){selectedExperiment=firdaEscOverlay(step,selectedExperiment);renderSelectedExperiment();renderContextNav()}return}
  if(step.page){
    activeDomain='esc';activatePage(step.page,false,'esc');
    if(step.page==='esc'&&step.pane&&WORKSPACE_PANES.esc?.[step.pane]){activeWorkspaceTab.esc=step.pane;setWorkspacePaneVisibility('esc',step.pane);renderWorkspaceTabs()}
    requestAnimationFrame(()=>document.getElementById(step.anchor)?.scrollIntoView({behavior:'smooth',block:'start'}));
  }
}
